def is_maximal_triangle_free(n, edges):
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # Check triangle-free
    for u in range(n):
        for v in adj[u]:
            if adj[u].intersection(adj[v]):
                return False, "Contains triangle"

    # Check maximal
    for u in range(n):
        for v in range(u+1, n):
            if v not in adj[u]:
                # If we add edge (u, v), does it create a triangle?
                # It creates a triangle iff u and v share a neighbor
                if not adj[u].intersection(adj[v]):
                    return False, f"Not maximal: can add edge ({u}, {v})"

    return True, "Valid"

edges = []
for u in range(8):
    for v in range(8, 16):
        edges.append((u, v))

print(is_maximal_triangle_free(16, edges))
print([list(e) for e in edges])

